-- Généré par tests/build_guide.lua depuis GUIDE.itIT.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.itIT = {
    { "h1", "Guida di Panorama" },
    { "p", "Come usare Panorama su WoW Forever e come configurare l'HDR su Windows." },
    { "p", "|cffffd100Prima fai una copia delle tue impostazioni.|r Panorama modifica impostazioni del gioco, e rimuovere l'addon non le ripristina. Prima di cambiare qualsiasi cosa, chiudi il gioco e copia la cartella |cffffd100WTF|r della tua installazione del gioco in un posto sicuro. Per tornare indietro, chiudi il gioco e rimetti quella copia al suo posto." },
    { "h2", "1. Aprire la finestra" },
    { "li", "Digita |cffffd100/pano|r oppure fai clic sinistro sul pulsante di Panorama sulla minimappa.", "-" },
    { "li", "Anche in Opzioni > AddOn > Panorama c'è un pulsante che la apre.", "-" },
    { "li", "Trascina la barra del titolo per spostare la finestra. Escape o il pulsante di chiusura la chiude.", "-" },
    { "p", "Il pulsante della minimappa:" },
    { "li", "Il clic sinistro apre o chiude la finestra.", "-" },
    { "li", "Il clic destro mostra i preset, annulla, ripeti e il riavvio della grafica.", "-" },
    { "li", "Trascinalo per spostarlo intorno alla minimappa. |cffffd100/pano minimap|r lo mostra o lo nasconde.", "-" },
    { "h2", "2. La finestra" },
    { "row", "Casella di ricerca (in alto a destra)", "Digita una parola per elencare le impostazioni corrispondenti di tutte le schede. Cancellala per tornare indietro." },
    { "row", "Schede", "Qualità, Interfaccia, Avanzate (impostazioni del gioco), poi Filtri, I miei filtri, Atmosfera (effetti di Panorama). La scheda aperta viene ricordata." },
    { "row", "Impostazioni avanzate (sotto il titolo)", "Non spuntata: nessuna scheda, una sola pagina con le preimpostazioni, le impostazioni principali di qualità (distanza visiva, nebbia volumetrica, ombre, occlusione ambientale, dettaglio dell'acqua, antialiasing, attenuazione nitidezza), l'uscita HDR e la luminosità di picco, il contrasto, la luminosità, la distanza della telecamera, il filtro, l'intensità del filtro e la modalità atmosfera. Spuntata: tutte le schede e tutte le impostazioni. Alla prima installazione è non spuntata; se usavi già Panorama, è spuntata. La ricerca trova sempre tutte le impostazioni." },
    { "row", "Annulla, Ripeti (sotto le schede, a destra)", "Annulla cancella la tua ultima modifica: cursore, casella, preset, filtro, atmosfera o Ripristina tutto. Ripeti la rimette. Le ultime 20 modifiche restano fino a |cffffd100/reload|r." },
    { "row", "Selettore della lingua (a destra delle schede)", "Lingua del gioco o una di dieci lingue. Cambiarla ricarica l'interfaccia." },
    { "row", "Guida (a sinistra della casella di ricerca)", "Apre questa guida nel gioco." },
    { "row", "Preset (scheda Qualità)", "Bassa, Media, Alta, Extra. Il preset che corrisponde alle tue impostazioni è evidenziato." },
    { "row", "Piè di pagina", "Applica a ogni accesso, pulsante minimappa, Ripristina tutto, riavvio del motore grafico." },
    { "p", "Fai clic sul titolo di una sezione per comprimerla o espanderla." },
    { "h3", "Una riga di impostazione" },
    { "li", "|cffffd100Cursore|r: il valore viene scritto quando rilasci il pulsante del mouse, non mentre trascini.", "-" },
    { "li", "|cffffd100Casella del valore|r accanto al cursore: digita un valore, poi premi Invio o fai clic altrove. Escape annulla, Tab passa alla casella successiva. La virgola funziona come separatore decimale. Il valore resta nell'intervallo del cursore.", "-" },
    { "li", "|cffffd100Pulsante Predefinito|r: riporta quell'impostazione al suo valore predefinito. Passaci sopra con il mouse per vedere il valore.", "-" },
    { "li", "|cffffd100Segno dorato|r a sinistra: hai cambiato questa impostazione.", "-" },
    { "li", "|cffffd100Stella gialla|r: anche un menu del gioco imposta questo valore. Passaci sopra con il mouse per vedere quale. Quel menu non rilegge il valore, quindi può mostrare un altro livello.", "-" },
    { "li", "|cffffd100Riga in grigio|r: dipende da un'altra impostazione che è disattivata (per esempio la densità della nebbia senza nebbia volumetrica, l'intensità della tinta senza una tinta). La riga indica quale impostazione cambiare.", "-" },
    { "li", "Passa il mouse su un'etichetta per leggere la sua guida completa.", "-" },
    { "h2", "3. Preset" },
    { "row", "Bassa", "Massime prestazioni. Visuale corta, senza ombre." },
    { "row", "Media", "Bilanciato. Buone prestazioni, ombre discrete." },
    { "row", "Alta", "Livello Alto del gioco. Ombre complete, tutti gli effetti." },
    { "row", "Extra", "Alta, con la visuale più lontana." },
    { "p", "I preset cambiano solo le impostazioni di qualità grafica della scheda Qualità. Non toccano fotocamera, mouse, interfaccia, nitidezza, bassa latenza, HDR né filtri." },
    { "p", "Hai cambiato idea? |cffffd100Annulla|r (sotto le schede, o |cffffd100/pano undo|r) ripristina le impostazioni di prima del preset." },
    { "h2", "4. Filtri" },
    { "p", "La scheda Filtri aggiunge effetti sopra l'immagine. Non cambiano nessuna impostazione del gioco." },
    { "li", "|cffffd100Tinta|r: fai clic su un'anteprima per applicarla subito (Seppia, Calda, Fredda, Notte, Smeraldo, Crepuscolo). |cffffd100Intensità della tinta|r imposta quanto è forte.", "-" },
    { "li", "|cffffd100Il mio filtro|r: usa uno dei tuoi filtri della scheda I miei filtri. Sostituisce la tinta, la vignettatura e la grana.", "-" },
    { "li", "|cffffd100Cielo|r: gli stessi colori come sfumatura, pieni in alto sullo schermo e più chiari in basso. |cffffd100Intensità del cielo|r imposta quanto è forte.", "-" },
    { "li", "|cffffd100Vignettatura|r: scurisce i bordi dello schermo.", "-" },
    { "li", "|cffffd100Grana|r: grana animata.", "-" },
    { "li", "|cffffd100Bande nere|r: bande in alto e in basso, da 0 a 20 % dello schermo ciascuna. Il gioco continua a elaborare ciò che nascondono, quindi non aumentano il frame rate.", "-" },
    { "h3", "Atmosfera" },
    { "p", "La scheda Atmosfera cambia da sola tinta, cielo, vignettatura e grana in base a dove ti trovi." },
    { "li", "|cffffd100Modalità|r (in alto nella scheda): |cffffd100Disattivo|r (la scheda Filtri si applica ovunque), |cffffd100Giorno e notte automatici|r (vedi Giorno e notte più sotto) o |cffffd100Atmosfera automatica|r. Disattivo per impostazione predefinita.", "-" },
    { "li", "|cffffd100Atmosfera automatica|r: questi filtri seguono il luogo e l'ora del giorno. I valori della scheda Filtri restano salvati e tornano quando cambi modalità. Senza Impostazioni avanzate, la pagina unica mostra solo la modalità e il luogo rilevato; spunta Impostazioni avanzate per modificare i contesti.", "-" },
    { "li", "|cffffd100Luogo|r: imposta tinta, vignettatura e grana. Ordine: spedizione o incursione, al chiuso, meteo (pioggia, neve, tempesta di sabbia), poi il tipo di zona: terre temperate, deserti e terre aride, terre innevate, giungla e palude, terre corrotte, terre vulcaniche, foreste arcane. Una zona non ancora nota conta come temperata. Il meteo conta solo se Intensità del meteo è maggiore di 0.", "-" },
    { "li", "|cffffd100Ora del giorno|r: imposta il cielo (giorno, alba e tramonto, notte). La notte segue il giorno e la notte del gioco; alba e tramonto seguono l'ora del server. Nessun cielo al chiuso o in una spedizione.", "-" },
    { "li", "La riga a destra mostra il luogo e l'ora del giorno rilevati adesso. Quando una spedizione, il chiuso o il meteo vengono prima di una zona che hai impostato, lo indica.", "-" },
    { "li", "|cffffd100Contesto da modificare|r: scegli un contesto, poi regola i suoi filtri sotto. Il pulsante Predefinito rende il valore fornito per quel contesto. Il menu ha cinque gruppi: |cffffd100Zone|r (la zona in cui ti trovi e quelle che hai impostato), |cffffd100Spedizione e interni|r, |cffffd100Meteo|r, |cffffd100Tipo di zona|r e |cffffd100Cielo (ora)|r. I primi quattro regolano tinta, vignettatura, grana e una preimpostazione grafica: si applica un solo luogo alla volta, nell'ordine indicato sopra. L'ultimo regola il cielo. Non serve regolare nulla per iniziare: ogni contesto ha già i suoi valori.", "-" },
    { "li", "|cffffd100Questa zona|r: prima voce dello stesso menu, con il nome della zona in cui ti trovi. Sceglila per dare a questa zona una tinta, una vignettatura e una grana proprie, partendo dal suo tipo di zona. Passa allora prima del tipo di zona, ma dopo spedizione, al chiuso e meteo. Le zone che imposti restano nel menu. |cffffd100Tipo di zona|r rimuove i valori della zona: torna a seguire il suo tipo di zona.", "-" },
    { "li", "|cffffd100Tutte le zone|r: sottomenu dello stesso menu, con tutte le zone conosciute. Scegline una per impostarla senza essere lì. Le zone sono ordinate per continente.", "-" },
    { "li", "|cffffd100Preimpostazione|r e |cffffd100Distanza dello scenario|r (prime righe di un luogo o di una zona): si applicano finché sei in quel luogo, sopra le tue impostazioni, con l'atmosfera automatica attiva o no. La distanza dello scenario del luogo viene prima di quella della preimpostazione. Le tue impostazioni restano salvate e tornano quando te ne vai. |cffffd100Le mie impostazioni|r non cambia nulla. Esempio: Bassa nelle spedizioni, Extra in una zona che ti piace. In una spedizione o incursione, la prima scelta del menu regola solo quella spedizione. Nella scheda Qualità, il pulsante |cffffd100Per luogo|r apre queste righe per il luogo in cui sei; mostra |cffffd100Qui: …|r finché un luogo applica le sue. In combattimento, la modifica attende la fine del combattimento.", "-" },
    { "li", "|cffffd100Il mio filtro|r (prima riga dei filtri di un luogo o di una zona): quel luogo usa uno dei tuoi filtri della scheda I miei filtri, con il suo contrasto, la sua luminosità e il suo gamma, finché l'atmosfera automatica è attiva.", "-" },
    { "li", "|cffffd100Giorno e notte|r (modalità |cffffd100Giorno e notte automatici|r): Panorama applica la |cffffd100Tinta diurna|r di giorno e la |cffffd100Tinta notturna|r di notte, secondo il giorno e la notte del gioco. Sostituiscono la tinta della scheda Filtri. Il passaggio è graduale dalle 19 alle 21 e dalle 5 alle 7 (ora del server). Le tinte diurna e notturna e le loro intensità si impostano con Impostazioni avanzate.", "-" },
    { "h2", "5. I miei filtri" },
    { "p", "La scheda I miei filtri (visibile con Impostazioni avanzate) serve a creare tutti i filtri tuoi che vuoi. |cffffd100Nuovo|r ne aggiunge uno, |cffffd100Elimina|r toglie il filtro aperto: la scheda Filtri, i luoghi e le zone che lo usavano tornano a Nessuno." },
    { "li", "|cffffd100Filtro da modificare|r: sceglie il filtro che le righe sotto regolano. |cffffd100Nome|r: dagli un nome (Invio per confermare).", "-" },
    { "li", "|cffffd100Rosso|r, |cffffd100Verde|r, |cffffd100Blu|r (in %): colore della tinta del filtro. |cffffd100Intensità della tinta|r: la sua forza.", "-" },
    { "li", "|cffffd100Vignettatura|r e |cffffd100Grana|r: quelle del filtro.", "-" },
    { "li", "|cffffd100Contrasto|r, |cffffd100Luminosità|r, |cffffd100Gamma|r: impostazioni dell'immagine che il filtro dà al gioco finché è applicato; poi tornano i tuoi valori. Le mie impostazioni: non cambia nulla. A seconda della modalità di visualizzazione possono restare senza effetto.", "-" },
    { "li", "Finché la scheda è aperta, il filtro mostrato si vede in diretta sul gioco.", "-" },
    { "li", "Per usare un filtro: sceglilo nella riga |cffffd100Il mio filtro|r della scheda Filtri (ovunque), oppure per un luogo o una zona nella scheda Atmosfera (atmosfera automatica attiva). Sostituisce allora la tinta, la vignettatura e la grana, le cui righe sono in grigio. Nessuno: non cambia nulla.", "-" },
    { "h2", "6. I tuoi valori e il gioco" },
    { "li", "Alla prima installazione, Panorama legge le impostazioni attuali del gioco. Non cambia nulla finché non muovi un controllo.", "-" },
    { "li", "Una modifica fatta nel menu Grafica del gioco o con |cffffd100/console|r compare nella finestra.", "-" },
    { "li", "|cffffd100Applica a ogni accesso|r (piè di pagina, attivo per impostazione predefinita): le impostazioni che hai cambiato in Panorama vengono scritte di nuovo a ogni accesso. Le altre seguono il menu Grafica del gioco.", "-" },
    { "li", "Una modifica fatta durante il combattimento viene applicata quando il combattimento finisce.", "-" },
    { "li", "Alcune impostazioni, come MSAA, richiedono un riavvio della grafica. Fai clic su |cffffd100Riavvia|r nel piè di pagina o digita |cffffd100/pano restart|r. Lo schermo sfarfalla per un secondo.", "-" },
    { "h2", "7. HDR su Windows" },
    { "p", "Le impostazioni HDR esistono nel gioco solo come comandi della console. Panorama le mostra nella scheda |cffffd100Avanzate|r, sezione |cffffd100HDR (solo console)|r. Serve un monitor che supporti l'HDR." },
    { "h3", "Passo 1: attivare l'HDR in Windows" },
    { "p", "Windows 11:" },
    { "li", "Apri |cffffd100Impostazioni > Sistema > Schermo|r.", "1." },
    { "li", "Seleziona il monitor HDR se ne hai più di uno.", "2." },
    { "li", "Attiva |cffffd100Usa HDR|r. Anche la scorciatoia |cffffd100Win + Alt + B|r lo attiva o lo disattiva.", "3." },
    { "p", "Windows 10: |cffffd100Impostazioni > Sistema > Schermo > Impostazioni colore HD di Windows|r (Windows HD Color settings), poi attiva |cffffd100Riproduci app e giochi HDR|r (Play HDR games and apps)." },
    { "p", "Controlla anche che l'HDR sia attivo nel menu del monitor stesso, se ha questa opzione." },
    { "p", "Disattiva l'|cffffd100HDR automatico|r (Auto HDR) di Windows 11: |cffffd100Impostazioni > Sistema > Schermo > HDR|r. Serve ai giochi senza HDR. WoW produce la propria immagine HDR." },
    { "h3", "Passo 2: trovare la luminosità massima del tuo monitor" },
    { "p", "Installa l'app gratuita |cffffd100Calibrazione HDR di Windows|r (Windows HDR Calibration) dal Microsoft Store ed eseguila. La luminanza massima che trova è la luminosità massima del tuo monitor, in nit." },
    { "p", "Senza l'app, usa la classificazione HDR del monitor: DisplayHDR 400 significa circa 400 nit, DisplayHDR 600 circa 600, DisplayHDR 1000 circa 1000." },
    { "h3", "Passo 3: impostare l'HDR in Panorama" },
    { "p", "Apri |cffffd100/pano|r, scheda |cffffd100Avanzate|r, sezione |cffffd100HDR (solo console)|r." },
    { "li", "Spunta |cffffd100Uscita HDR|r.", "1." },
    { "li", "Spunta |cffffd100Usa luminosità di picco|r o |cffffd100Usa luminosità di riferimento|r: l'uno o l'altro, mai entrambi. Senza nessuno, l'immagine diventa scura.", "2." },
    { "p", "|cffffd100Modo luminosità massima (consigliato)|r" },
    { "li", "Spunta |cffffd100Usa luminosità di picco|r.", "-" },
    { "li", "Imposta |cffffd100Luminosità di picco (nit)|r sul valore trovato nel passo 2.", "-" },
    { "li", "|cffffd100Intensità HDR|r funziona solo in questo modo. Il valore predefinito del gioco è 2. Cambialo a piccoli passi e confronta: Blizzard non documenta il suo effetto esatto.", "-" },
    { "p", "|cffffd100Modo luminosità di riferimento|r" },
    { "li", "Spunta |cffffd100Usa luminosità di riferimento|r.", "-" },
    { "li", "|cffffd100Luminosità di riferimento (nit)|r è la luminosità del bianco nella scena. 203 è il valore standard. Aumentalo se l'immagine sembra troppo scura in una stanza luminosa. Intensità HDR non ha effetto in questo modo.", "-" },
    { "p", "Se l'immagine non cambia, fai clic su |cffffd100Riavvia|r nel piè di pagina." },
    { "h3", "Risoluzione dei problemi HDR" },
    { "row", "Immagine molto scura", "Spunta uno dei due modi di luminosità." },
    { "row", "Immagine grigia o sbiadita", "Attiva l'HDR in Windows (passo 1) e nel menu del monitor." },
    { "row", "HDR automatico attivo in Windows", "Disattivalo (passo 1)." },
    { "row", "Luci troppo forti o piatte", "Imposta la luminosità massima sul valore reale del tuo monitor (passo 2)." },
    { "row", "Vuoi l'HDR disattivato", "Togli la spunta a |cffffd100Uscita HDR|r." },
    { "p", "Ogni riga HDR ha un pulsante Predefinito che ripristina il valore del gioco." },
    { "h2", "8. Comandi" },
    { "row", "|cffffd100/pano|r", "Apre o chiude la finestra" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Applica un preset" },
    { "row", "|cffffd100/pano undo|r", "Annulla l'ultima modifica" },
    { "row", "|cffffd100/pano redo|r", "Rimette la modifica appena annullata" },
    { "row", "|cffffd100/pano reset|r", "Riporta ogni impostazione e ogni filtro al valore predefinito" },
    { "row", "|cffffd100/pano status|r", "Mostra nella chat il luogo e il momento rilevati e i filtri applicati ora (durante una dissolvenza, i valori di arrivo)" },
    { "row", "|cffffd100/pano apply|r", "Scrive di nuovo le impostazioni cambiate in Panorama" },
    { "row", "|cffffd100/pano restart|r", "Riavvia il motore grafico" },
    { "row", "|cffffd100/pano minimap|r", "Mostra o nasconde il pulsante della minimappa" },
    { "h2", "9. Ripristino" },
    { "li", "Il pulsante |cffffd100Predefinito|r di ogni riga ripristina quell'impostazione.", "-" },
    { "li", "Il pulsante |cffffd100Predefiniti|r del menu Grafica del gioco ripristina solo le impostazioni che quel menu gestisce, e Panorama lo segue. Usa i pulsanti Predefinito in |cffffd100/pano|r per le altre e per i filtri.", "-" },
    { "li", "|cffffd100Ripristina tutto|r (piè di pagina, con conferma) o |cffffd100/pano reset|r: riporta ogni impostazione modificata in Panorama e ogni filtro al valore predefinito. |cffffd100Annulla|r la annulla fino a |cffffd100/reload|r. Anche la scheda Atmosfera e le zone impostate vengono ripristinate. Anche i tuoi filtri della scheda I miei filtri vengono cancellati.", "-" },
}
